import {test, expect, APIRequestContext, Page, Locator} from '@playwright/test';
import fs from 'node:fs';

// Opt-in: the manifest is generated by fixtures/jobs_hiring.exs in local Docker.
const manifest = process.env.JOBS_HIRING_FIXTURE;
const fixture = manifest ? JSON.parse(fs.readFileSync(manifest, 'utf8')) : null;
const apiUrl = process.env.API_BASE_URL ?? 'http://localhost:4000';
const appUrl = process.env.BASE_URL ?? 'http://localhost:8081';
test.skip(!fixture, 'Set JOBS_HIRING_FIXTURE to the isolated local QA manifest.');
test.describe.configure({mode: 'default', timeout: 120_000});
test.use({actionTimeout: 15_000, launchOptions: {executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE}});
const tokens: Record<string, string> = {};
let request: APIRequestContext;
let sequence = 0;
const title = (name: string) => `${name} ${fixture.run_id}-${++sequence} [synthetic QA]`;
const escape = (value: string) => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

test.beforeAll(async ({playwright}) => {
  expect(['localhost', '127.0.0.1']).toContain(new URL(apiUrl).hostname);
  expect(['localhost', '127.0.0.1']).toContain(new URL(appUrl).hostname);
  request = await playwright.request.newContext({baseURL: apiUrl});
  for (const role of ['owner', 'candidate', 'second', 'foreign', 'newcomer']) {
    const r = await request.post('/api/auth/login', {data: fixture[role]});
    expect(r.status()).toBe(200);
    tokens[role] = (await r.json()).token;
  }
});
test.afterAll(async () => {await request?.dispose();});

async function call(role: string | null, method: string, path: string, data?: object, status = 200) {
  const response = await request.fetch(path, {method, data,
    headers: role ? {authorization: `Bearer ${tokens[role]}`} : {}});
  expect(response.status(), `${method} ${path}`).toBe(status);
  return status === 204 ? {} : response.json();
}
async function job(name: string, overrides: object = {}) {
  return (await call('owner', 'POST', '/api/jobs', {
    title: title(name), organization_id: fixture.organization_id,
    description: 'Synthetic local verification vacancy; not a real opening.',
    location: 'Bandung', industry: 'Technology', employment_type: 'full-time', work_mode: 'remote',
    requirements: ['Elixir', 'SQL'], salary_min: 5_000_000, salary_max: 9_000_000, currency: 'IDR', status: 'active', ...overrides,
  }, 201)).data;
}
async function apply(jobId: string, role = 'candidate') {
  return (await call(role, 'POST', `/api/jobs/${jobId}/applications`, {consent: true, cover_letter: 'Local synthetic application.'}, 201)).data;
}
async function advance(application: any, next: string, extra: object = {}) {
  return (await call('owner', 'PATCH', `/api/applications/${application.id}`, {
    status: next, expected_status: application.status, note: `Shared note: ${next}`, ...extra,
  })).data;
}
async function at(stage: string) {
  let app = await apply((await job('Stage matrix')).id);
  for (const next of ['reviewing', 'interview', 'offer', 'hired']) {
    if (app.status === stage) break;
    app = await advance(app, next);
  }
  expect(app.status).toBe(stage);
  return app;
}

test('visitors browse and open jobs, and new accounts apply without organization membership', async ({page}) => {
  const guest = await call(null, 'GET', `/api/jobs/${fixture.published_job_id}`);
  expect(guest.data.can_manage).toBe(false);
  await call(null, 'GET', `/api/jobs/${fixture.draft_job_id}`, undefined, 404);
  await call(null, 'POST', `/api/jobs/${fixture.published_job_id}/applications`, {consent: true}, 401);
  const fresh = await call('newcomer', 'GET', '/api/jobs');
  expect(fresh.organizations).toEqual([]);
  expect(fresh.meta.total).toBeGreaterThan(0);
  const submitted = await apply((await job('Public applicant')).id, 'newcomer');
  expect(submitted.status).toBe('applied');
  await call('foreign', 'GET', `/api/applications/${submitted.id}`, undefined, 404);

  const privateRequests: string[] = [];
  page.on('request', r => {
    if (r.url().includes('/api/me/') || r.url().includes('/api/applications')) privateRequests.push(r.url());
  });
  await page.goto(appUrl); await semantics(page);
  const loaded = page.waitForResponse(r => r.request().method() === 'GET' && new URL(r.url()).pathname === '/api/jobs');
  await page.getByRole('button', {name: /^Explore jobs/}).first().click();
  expect((await loaded).status()).toBe(200);
  await openJob(page, 'Browser vacancy [synthetic QA]');
  const applyButton = page.getByRole('button', {name: /Sign in to apply/});
  await reveal(page, applyButton); await applyButton.click();
  await expect(page.getByRole('textbox').first()).toBeVisible();
  await expect(page.getByRole('button', {name: /^Log in/}).first()).toBeVisible();
  expect(privateRequests).toEqual([]);
  await page.goto(`${appUrl}/#/jobs`); await semantics(page);
  await expect(page.getByRole('textbox').first()).toBeVisible();
  await page.reload(); await semantics(page);
  await openJob(page, 'Browser vacancy [synthetic QA]');
  await page.setViewportSize({width: 390, height: 844});
  await reveal(page, applyButton); await expect(applyButton).toBeVisible();
});

test('vacancy CRUD, validation, publication, expiration and tenant permissions', async () => {
  await call(null, 'GET', '/api/jobs');
  await call(null, 'GET', '/api/jobs?scope=manage', undefined, 401);
  await call('candidate', 'GET', '/api/jobs/invalid', undefined, 404);
  await call('candidate', 'GET', `/api/jobs/${fixture.draft_job_id}`, undefined, 404);
  await call('candidate', 'GET', `/api/jobs/${fixture.foreign_job_id}`);
  const listing = await job('CRUD', {status: 'draft', created_by: fixture.candidate.id, synthetic: true, posted_at: '2099-01-01T00:00:00Z'});
  expect(listing.status).toBe('draft'); expect(listing.synthetic).toBe(false); expect(listing.posted_at).toBeNull();
  await call('candidate', 'GET', `/api/jobs/${listing.id}`, undefined, 404);
  await call('foreign', 'PATCH', `/api/jobs/${listing.id}`, {title: 'Stolen'}, 404);
  await call('candidate', 'DELETE', `/api/jobs/${listing.id}`, undefined, 404);
  await call('candidate', 'POST', '/api/jobs', {organization_id: fixture.organization_id}, 403);
  for (const invalid of [{title: ' '}, {employment_type: 'other'}, {salary_min: -1}, {salary_max: 1}, {currency: 'INVALID'}]) {
    await call('owner', 'PATCH', `/api/jobs/${listing.id}`, invalid, 422);
  }
  const updated = (await call('owner', 'PATCH', `/api/jobs/${listing.id}`, {status: 'active', title: title('Edited CRUD'), organization_id: fixture.foreign_organization_id})).data;
  expect(updated.organization_id).toBe(fixture.organization_id); expect(updated.posted_at).toBeTruthy();
  expect((await call('candidate', 'GET', `/api/jobs/${listing.id}`)).data.title).toBe(updated.title);
  await call('candidate', 'PATCH', `/api/jobs/${listing.id}`, {title: 'Unauthorized edit'}, 403);
  await call('owner', 'PATCH', `/api/jobs/${listing.id}`, {status: 'expired'});
  await call('candidate', 'GET', `/api/jobs/${listing.id}`, undefined, 404);
  const managed = await call('owner', 'GET', `/api/jobs?scope=manage&status=expired&q=${encodeURIComponent(updated.title)}`);
  expect(managed.data.map((j: any) => j.id)).toContain(listing.id);
  await call('owner', 'DELETE', `/api/jobs/${listing.id}`, undefined, 204);
  await call('owner', 'GET', `/api/jobs/${listing.id}`, undefined, 404);
});

test('vacancy search, every employment/work mode, salary/currency and pagination', async () => {
  const prefix = `Filter matrix ${fixture.run_id}`;
  const types = ['full-time', 'part-time', 'internship', 'contract', 'freelance'];
  const modes = ['remote', 'hybrid', 'onsite'];
  const listings = [];
  for (let i = 0; i < 15; i++) listings.push(await job(prefix, {
    employment_type: types[i % 5], work_mode: modes[i % 3],
    location: i % 2 ? 'Jakarta' : 'Bandung', salary_max: 10_000_000 + i, currency: i % 5 ? 'IDR' : 'USD',
  }));
  await job(prefix, {status: 'draft'});
  const query = `q=${encodeURIComponent(prefix)}`;
  const first = await call('candidate', 'GET', `/api/jobs?${query}&page_size=12`);
  const second = await call('candidate', 'GET', `/api/jobs?${query}&page_size=12&page=2`);
  expect(first.meta.total).toBe(15); expect(first.data).toHaveLength(12); expect(second.data).toHaveLength(3);
  expect(new Set([...first.data, ...second.data].map(j => j.id)).size).toBe(15);
  for (const employment_type of types) {
    const result = await call('candidate', 'GET', `/api/jobs?${query}&employment_type=${employment_type}`);
    expect(result.meta.total).toBe(3); expect(result.data.every((j: any) => j.employment_type === employment_type)).toBe(true);
  }
  for (const work_mode of modes) {
    const result = await call('candidate', 'GET', `/api/jobs?${query}&work_mode=${work_mode}`);
    expect(result.meta.total).toBe(5); expect(result.data.every((j: any) => j.work_mode === work_mode)).toBe(true);
  }
  const combined = await call('candidate', 'GET', `/api/jobs?${query}&location=jak&industry=TECH&work_mode=hybrid&employment_type=part-time`);
  const expected = listings.filter(j => j.location === 'Jakarta' && j.work_mode === 'hybrid' && j.employment_type === 'part-time');
  expect(combined.data.map((j: any) => j.id).sort()).toEqual(expected.map(j => j.id).sort());
  const salary = await call('candidate', 'GET', `/api/jobs?${query}&sort=salary&currency=IDR&salary_min=10000008&page_size=50`);
  expect(salary.data.every((j: any) => j.currency === 'IDR' && j.salary_max >= 10_000_008)).toBe(true);
  expect(salary.data.map((j: any) => j.salary_max)).toEqual(salary.data.map((j: any) => j.salary_max).sort((a: number, b: number) => b - a));
  for (const invalid of ['page=0', 'page_size=51', 'salary_min=abc', 'sort=salary', 'work_mode=unknown']) {
    await call('candidate', 'GET', `/api/jobs?${invalid}`, undefined, 400);
  }
});

test('application consent, selected resume snapshot, duplicate protection and full hiring sequence', async () => {
  const listing = await job('Hiring lifecycle');
  await call('candidate', 'POST', `/api/jobs/${listing.id}/applications`, {}, 422);
  await call('owner', 'POST', `/api/jobs/${listing.id}/applications`, {consent: true}, 409);
  const before = (await call('candidate', 'GET', '/api/me/cv')).data;
  let app = await apply(listing.id);
  expect(app.profile.resume_document.id).toBe(fixture.resume_document_id);
  expect(app.profile.pdf_documents).toBeUndefined();
  await call('candidate', 'POST', `/api/jobs/${listing.id}/applications`, {consent: true}, 409);
  await call('foreign', 'GET', `/api/applications/${app.id}`, undefined, 404);
  await call('second', 'GET', `/api/applications/${app.id}`, undefined, 404);
  await call('candidate', 'PATCH', '/api/me/cv', {headline: 'Changed after submission [synthetic QA]'});
  expect((await call('owner', 'GET', `/api/applications/${app.id}`)).data.profile.headline).toBe(before.headline);
  for (const next of ['reviewing', 'interview', 'offer', 'hired']) {
    app = await advance(app, next, next === 'interview' ? {interview_at: new Date(Date.now() + 3_600_000).toISOString()} : {});
  }
  expect(app.history.map((e: any) => e.status)).toEqual(['applied', 'reviewing', 'interview', 'offer', 'hired']);
  expect(app.next_statuses).toEqual([]); expect(app.can_chat).toBe(false);
  await call('owner', 'PATCH', `/api/applications/${app.id}`, {status: 'reviewing', expected_status: 'hired'}, 409);
  await call('owner', 'DELETE', `/api/jobs/${listing.id}`, undefined, 409);
});

test('rejection and withdrawal at every active stage, invalid transitions and read-only history', async () => {
  const stages = ['applied', 'reviewing', 'interview', 'offer'];
  for (const stage of stages) for (const exit of ['rejected', 'withdrawn']) {
    let app = await at(stage);
    await call('candidate', 'PATCH', `/api/applications/${app.id}`, {status: 'hired', expected_status: stage}, 409);
    await call('owner', 'PATCH', `/api/applications/${app.id}`, {status: 'hired', expected_status: 'stale'}, 409);
    if (stage === 'reviewing') {
      for (const value of ['invalid', '2020-01-01T00:00:00Z', [], 123]) {
        await call('owner', 'PATCH', `/api/applications/${app.id}`, {status: 'interview', expected_status: stage, interview_at: value}, 422);
      }
    }
    if (stage === 'offer' && exit === 'withdrawn') {
      await call('owner', 'PATCH', `/api/jobs/${app.job_id}`, {status: 'expired'});
      await call('candidate', 'POST', `/api/jobs/${app.job_id}/applications`, {consent: true}, 404);
      await call('candidate', 'POST', `/api/chats/application/${app.id}/messages`, {body: 'Existing process remains accessible.', client_id: `followup-${app.id}`}, 201);
    }
    app = (await call(exit === 'withdrawn' ? 'candidate' : 'owner', 'PATCH', `/api/applications/${app.id}`, {status: exit, expected_status: stage, note: 'Shared exit reason'})).data;
    expect(app.status).toBe(exit); expect(app.next_statuses).toEqual([]);
    await call('owner', 'PATCH', `/api/applications/${app.id}`, {status: 'reviewing', expected_status: exit}, 409);
    const history = await call('candidate', 'GET', `/api/chats/application/${app.id}/messages`);
    expect(history.thread.can_send).toBe(false);
    await call('candidate', 'POST', `/api/chats/application/${app.id}/messages`, {body: 'Closed', client_id: `closed-${app.id}`}, 409);
  }
});

test('application pagination, stage counts and employer job filtering', async () => {
  const apps = [];
  for (let i = 0; i < 26; i++) apps.push(await apply((await job('Pagination')).id, 'second'));
  await advance(apps[0], 'reviewing');
  const first = await call('second', 'GET', '/api/applications');
  const second = await call('second', 'GET', '/api/applications?page=2');
  expect(first.meta.total).toBe(26); expect(first.data).toHaveLength(25); expect(second.data).toHaveLength(1);
  expect(new Set([...first.data, ...second.data].map(a => a.id)).size).toBe(26);
  expect(first.counts).toEqual({applied: 25, reviewing: 1});
  const filter = await call('owner', 'GET', `/api/applications?scope=hiring&job_id=${apps[0].job_id}&status=reviewing`);
  expect(filter.meta.total).toBe(1); expect(filter.data[0].id).toBe(apps[0].id);
  for (const invalid of ['scope=unknown', 'status=unknown', 'job_id=invalid', 'page=0']) {
    await call('candidate', 'GET', `/api/applications?${invalid}`, undefined, 400);
  }
});

test('real concurrent submissions and hiring updates do not duplicate or lose history', async () => {
  const listing = await job('Concurrent application');
  const applications = await Promise.all([1, 2].map(() => request.post(`/api/jobs/${listing.id}/applications`, {
    headers: {authorization: `Bearer ${tokens.candidate}`}, data: {consent: true},
  })));
  expect(applications.map(r => r.status()).sort()).toEqual([201, 409]);
  const app = (await applications.find(r => r.status() === 201)!.json()).data;
  const updates = await Promise.all(['reviewing', 'rejected'].map(status => request.patch(`/api/applications/${app.id}`, {
    headers: {authorization: `Bearer ${tokens.owner}`}, data: {status, expected_status: 'applied'},
  })));
  expect(updates.map(r => r.status()).sort()).toEqual([200, 409]);
  expect((await call('candidate', 'GET', `/api/applications/${app.id}`)).data.history).toHaveLength(2);
});

test('concurrent vacancy deletion and applying preserve integrity without server errors', async () => {
  for (let i = 0; i < 8; i++) {
    const listing = await job('Delete/apply race');
    const [application, deletion] = await Promise.all([
      request.post(`/api/jobs/${listing.id}/applications`, {headers: {authorization: `Bearer ${tokens.candidate}`}, data: {consent: true}}),
      request.delete(`/api/jobs/${listing.id}`, {headers: {authorization: `Bearer ${tokens.owner}`}}),
    ]);
    const pair = [application.status(), deletion.status()];
    expect([[201, 409], [404, 204]], `delete/apply attempt ${i + 1}: ${pair.join('/')}`).toContainEqual(pair);
  }
});

async function frames(page: Page) {await page.evaluate(() => new Promise<void>(r => requestAnimationFrame(() => requestAnimationFrame(() => r()))));}
async function semantics(page: Page) {
  if (await page.locator('flt-semantics').count()) return;
  await page.locator('flt-semantics-placeholder').waitFor({state: 'attached'});
  await frames(page);
  await page.locator('flt-semantics-placeholder').evaluate((el: HTMLElement) => el.click());
}
async function reveal(page: Page, locator: Locator) {
  for (let i = 0; i < 12; i++) {
    if (await locator.count() && await locator.first().isVisible()) return;
    await page.mouse.wheel(0, 450); await frames(page);
  }
  await locator.first().waitFor({state: 'visible'});
}
async function fill(page: Page, locator: Locator, value: string) {
  await reveal(page, locator); await locator.first().click(); await frames(page);
  await locator.first().press('ControlOrMeta+A'); await frames(page);
  await locator.first().press('Backspace'); await frames(page);
  await locator.first().pressSequentially(value, {delay: 20}); await frames(page);
  await expect(locator.first()).toHaveValue(value);
  await locator.first().press('Tab');
}
async function login(page: Page, role: string) {
  await page.goto(appUrl); await semantics(page);
  await page.getByRole('button', {name: /^Log in/}).first().click();
  await fill(page, page.getByRole('textbox').nth(0), fixture[role].email);
  await fill(page, page.getByRole('textbox').nth(1), fixture[role].password);
  const response = page.waitForResponse(r => r.url().endsWith('/api/auth/login') && r.request().method() === 'POST');
  await page.getByRole('button', {name: /^Log in/}).first().click();
  expect((await response).status()).toBe(200);
  await page.getByRole('button', {name: /Go to dashboard/}).click();
  await page.goto(`${appUrl}/#/jobs`); await semantics(page);
}
async function openJob(page: Page, name: string) {
  const search = page.getByRole('textbox').first();
  const result = page.waitForResponse(r => r.request().method() === 'GET' && new URL(r.url()).pathname === '/api/jobs' && new URL(r.url()).searchParams.get('q') === name);
  await fill(page, search, name); expect((await result).status()).toBe(200);
  const card = page.getByRole('button', {name: new RegExp(escape(name))}).first();
  await reveal(page, card); await card.click();
}

test('employer browser creates, edits, publishes and deletes an unused vacancy', async ({page}) => {
  await login(page, 'owner');
  await page.getByRole('button', {name: /Post a job/}).click();
  const initial = title('UI created');
  await fill(page, page.getByRole('textbox', {name: /^Job title/}), initial);
  await fill(page, page.getByRole('textbox', {name: /^Location/}), 'Bandung');
  await fill(page, page.getByRole('textbox', {name: /^Industry/}), 'Technology');
  await fill(page, page.getByRole('textbox', {name: /^About the role/}), 'Synthetic employer browser verification.');
  const created = page.waitForResponse(r => r.request().method() === 'POST' && new URL(r.url()).pathname === '/api/jobs');
  const save = page.getByRole('button', {name: /Save listing/}); await reveal(page, save); await save.click();
  const creation = await created; expect(creation.status()).toBe(201);
  const listing = (await creation.json()).data; expect(listing.status).toBe('draft');
  await page.getByRole('button', {name: /Post a job/}).waitFor();
  await openJob(page, initial);
  const edit = page.getByRole('button', {name: /Edit listing/}); await reveal(page, edit); await edit.click();
  const updatedTitle = title('UI edited');
  await fill(page, page.getByRole('textbox', {name: /^Job title/}), updatedTitle);
  const status = page.getByRole('combobox', {name: /Listing status/}).or(page.getByRole('button', {name: /Listing status/})).first();
  await reveal(page, status); await status.click();
  await page.getByRole('menuitem', {name: 'active', exact: true}).or(page.getByRole('option', {name: 'active', exact: true})).first().click({timeout: 10_000});
  const saved = page.waitForResponse(r => r.request().method() === 'PATCH' && r.url().endsWith(`/api/jobs/${listing.id}`));
  await reveal(page, save); await save.click(); expect((await saved).status()).toBe(200);
  expect((await call('candidate', 'GET', `/api/jobs/${listing.id}`)).data.title).toBe(updatedTitle);
  const remove = page.getByRole('button', {name: /Delete listing/}); await reveal(page, remove); await remove.click();
  const deleted = page.waitForResponse(r => r.request().method() === 'DELETE' && r.url().endsWith(`/api/jobs/${listing.id}`));
  await page.getByRole('button', {name: 'Delete', exact: true}).click(); expect((await deleted).status()).toBe(204);
});

test('candidate and employer browsers apply, exchange live chat and finish all hiring stages', async ({browser}) => {
  const candidateContext = await browser.newContext({viewport: {width: 1440, height: 1100}});
  const employerContext = await browser.newContext({viewport: {width: 1440, height: 1100}});
  const candidate = await candidateContext.newPage(), employer = await employerContext.newPage();
  try {
    await login(candidate, 'candidate'); await openJob(candidate, 'Browser vacancy [synthetic QA]');
    await candidate.getByRole('button', {name: /Apply for this role/}).click();
    const submit = candidate.getByRole('button', {name: /Submit application/});
    await reveal(candidate, submit); await expect(submit).toBeDisabled();
    await candidate.getByRole('checkbox').first().click();
    const submitted = candidate.waitForResponse(r => r.request().method() === 'POST' && r.url().endsWith('/applications'));
    await submit.click(); const response = await submitted; expect(response.status()).toBe(201);
    const application = (await response.json()).data;
    await login(employer, 'owner'); await openJob(employer, 'Browser vacancy [synthetic QA]');
    const review = employer.getByRole('button', {name: /Review applicants/}); await reveal(employer, review); await review.click();
    const card = employer.getByRole('button', {name: /Browser vacancy/}).first(); await reveal(employer, card); await card.click();
    let liveReceived = false;
    // Attach before opening chat so the socket's first delivery is observed.
    candidate.on('websocket', socket => socket.on('framereceived', frame => {
      try {const m = JSON.parse(frame.payload.toString()); if (m[3] === 'message_created' && m[4]?.body === 'Employer browser reply') liveReceived = true;} catch {}
    }));
    await candidate.getByRole('button', {name: /Open chat/}).click();
    await employer.getByRole('button', {name: /Open chat/}).click();
    const draft = employer.getByRole('textbox').last(); await draft.click(); await frames(employer); await draft.pressSequentially('Employer browser reply');
    const sent = employer.waitForResponse(r => r.request().method() === 'POST' && r.url().includes('/chats/application/'));
    await employer.getByRole('button', {name: /Send message/}).click(); expect((await sent).status()).toBe(201);
    await expect.poll(async () => (await call('candidate', 'GET', `/api/chats/application/${application.id}/messages`)).data.length).toBe(1);
    await expect.poll(() => liveReceived).toBe(true);
    await employer.getByRole('button', {name: /Back/}).first().click();
    for (const stage of ['reviewing', 'interview', 'offer', 'hired']) {
      await employer.getByRole('button', {name: `Move to ${stage[0].toUpperCase()}${stage.slice(1)}`, exact: true}).click();
      await fill(employer, employer.getByRole('textbox').last(), `Browser shared note: ${stage}`);
      const changed = employer.waitForResponse(r => r.request().method() === 'PATCH' && r.url().endsWith(`/api/applications/${application.id}`));
      await employer.getByRole('button', {name: `Move to ${stage[0].toUpperCase()}${stage.slice(1)}`, exact: true}).last().click(); expect((await changed).status()).toBe(200);
    }
    const history = (await call('candidate', 'GET', `/api/applications/${application.id}`)).data;
    expect(history.history.map((e: any) => e.status)).toEqual(['applied', 'reviewing', 'interview', 'offer', 'hired']);
    expect(history.history.slice(1).every((e: any) => e.note.startsWith('Browser shared note:'))).toBe(true);
    await candidate.setViewportSize({width: 390, height: 844});
    await candidate.getByRole('button', {name: /Refresh messages/}).click();
    await expect(candidate.getByText(/This conversation is read-only/)).toBeVisible();
  } finally {await candidateContext.close(); await employerContext.close();}
});

test('guest application returns to the selected job after signing in and reloading login', async ({page}) => {
  await page.goto(`${appUrl}/#/jobs/${fixture.published_job_id}`); await semantics(page);
  const apply = page.getByRole('button', {name: /Sign in to apply/});
  await reveal(page, apply); await apply.click();
  await page.reload(); await semantics(page);
  await fill(page, page.getByRole('textbox').nth(0), fixture.newcomer.email);
  await fill(page, page.getByRole('textbox').nth(1), fixture.newcomer.password);
  await page.getByRole('button', {name: /^Log in/}).first().click();
  await expect(page.getByText(/^Profile to share/)).toBeVisible();
  await expect(page).toHaveURL(new RegExp(`/jobs/${fixture.published_job_id}\\?apply=1$`));
  // Viewing the form is read-only; no duplicate application is submitted.
});

test('dashboard hiring filters survive resize, reload and browser history', async ({page}) => {
  await login(page, 'owner');
  const location = `${appUrl}/#/dashboard?view=jobs&tab=applications&scope=hiring&status=reviewing`;
  const loads: string[] = [];
  page.on('request', r => {if (new URL(r.url()).pathname === '/api/applications') loads.push(r.url());});
  await page.goto(location); await semantics(page);
  await expect.poll(() => loads.length).toBeGreaterThan(0);
  await expect(page.getByRole('checkbox', {name: 'Hiring', exact: true})).toBeChecked();
  await page.setViewportSize({width: 390, height: 844}); await frames(page);
  await expect(page.getByRole('combobox', {name: /Application stage/}).or(page.getByRole('button', {name: /Application stage/})).first()).toBeVisible();
  expect(new URL(loads.at(-1)!).searchParams.get('scope')).toBe('hiring');
  expect(new URL(loads.at(-1)!).searchParams.get('status')).toBe('reviewing');
  await page.reload(); await semantics(page);
  await expect(page.getByRole('checkbox', {name: 'Hiring', exact: true})).toBeChecked();
  await page.setViewportSize({width: 1440, height: 1000}); await frames(page);
  await page.getByRole('button', {name: 'Vacancies', exact: true}).first().click();
  await expect(page).toHaveURL(/tab=vacancies/);
  await page.reload(); await semantics(page);
  await expect(page.getByRole('button', {name: /Post a job/})).toBeVisible();
  await page.goBack(); await semantics(page);
  await expect(page).toHaveURL(/scope=hiring&status=reviewing/);
  await expect(page.getByRole('checkbox', {name: 'Hiring', exact: true})).toBeChecked();
  await page.goForward(); await semantics(page);
  await expect(page).toHaveURL(/tab=vacancies/);
});
